import axios from "axios";
import { getAccessToken } from "./userService";

const KEYCLOAK_BASE_URL = process.env.KEYCLOAK_BASE_URL!;
const REALM = process.env.REALM!;
const CLIENT_NAME = process.env.CLIENT_NAME!; 

/**
 * Keycloak Client Type
 */
type KeycloakClient = {
  id: string;
  clientId: string;
};

/**
 * Keycloak Role Type
 */
type KeycloakRole = {
  id: string;
  name: string;
  description?: string;
  composite?: boolean;
  clientRole?: boolean;
  containerId?: string;
};

/**
 * Get all composite roles for a given clientId
 */
export async function getAllClientRoles(
  clientId: string
): Promise<KeycloakRole[]> {
  const token = await getAccessToken();

  if (!token) {
    throw new Error("Failed to get access token from Keycloak");
  }

  // -------------------------------
  // Step 1: Get client UUID
  // -------------------------------
  const clientRes = await axios.get<KeycloakClient[]>(
    `${KEYCLOAK_BASE_URL}/admin/realms/${REALM}/clients`,
    {
      params: { clientId },
      headers: {
        Authorization: `Bearer ${token}`,
        "Content-Type": "application/json",
      },
    }
  );

  if (!Array.isArray(clientRes.data) || clientRes.data.length === 0) {
    throw new Error(`Client not found for clientId: ${clientId}`);
  }

  const clientUUID = clientRes.data[0].id;

  // -------------------------------
  // Step 2: Fetch all roles
  // -------------------------------
  const rolesRes = await axios.get<KeycloakRole[]>(
    `${KEYCLOAK_BASE_URL}/admin/realms/${REALM}/clients/${clientUUID}/roles`,
    {
      headers: {
        Authorization: `Bearer ${token}`,
        "Content-Type": "application/json",
      },
    }
  );

  // -------------------------------
  // Step 3: Filter composite roles
  // -------------------------------
  const compositeRoles = rolesRes.data.filter(
    (role) => role.composite === true
  );

  return compositeRoles;
}